  'results.submit_error_auth': { fr: 'Session invalide — reconnecte-toi pour enregistrer tes scores.', en: 'Invalid session — log in again to save your scores.', es: 'Sesión inválida — vuelve a iniciar sesión para guardar tus puntuaciones.', de: 'Ungültige Sitzung — melde dich erneut an, um deine Punkte zu speichern.', pt: 'Sessão inválida — faça login novamente para salvar suas pontuações.', it: 'Sessione non valida — accedi di nuovo per salvare i punteggi.', ar: 'جلسة غير صالحة — سجّل الدخول مجددًا لحفظ نتائجك.', ja: 'セッション無効 — 再ログインしてスコアを保存してください。', ko: '세션이 유효하지 않음 — 다시 로그인하여 점수를 저장하세요.', zh: '会话无效——请重新登录以保存分数。', pl: 'Nieprawidłowa sesja — zaloguj się ponownie, aby zapisywać wyniki.' },
