  'economy.challenges_free': { fr: 'Les défis et les revanches sont toujours gratuits.', en: 'Challenges and rematches are always free.', es: 'Los desafíos y las revanchas siempre son gratis.', de: 'Herausforderungen und Revanchen sind immer kostenlos.', pt: 'Desafios e revanches são sempre grátis.', it: 'Sfide e rivincite sono sempre gratuite.', ar: 'التحديات والمباريات الثأرية مجانية دائمًا.', ja: 'チャレンジとリベンジはいつでも無料です。', ko: '도전과 리매치는 항상 무료예요.', zh: '挑战和复仇赛始终免费。', pl: 'Wyzwania i rewanże są zawsze darmowe.' },
  'economy.theme_limit_title': { fr: 'Nouveau thème', en: 'New theme', es: 'Nuevo tema', de: 'Neues Thema', pt: 'Novo tema', it: 'Nuovo tema', ar: 'موضوع جديد', ja: '新しいテーマ', ko: '새 테마', zh: '新主题', pl: 'Nowy temat' },
  'economy.theme_limit_body': { fr: 'Tu joues déjà {used} thèmes sur {limit}. Regarde une pub pour en débloquer {n} de plus, pour toujours. Tes thèmes déjà joués restent gratuits.', en: 'You already play {used} of {limit} themes. Watch an ad to unlock {n} more, for good. Themes you have played stay free.', es: 'Ya juegas {used} de {limit} temas. Mira un anuncio para desbloquear {n} más, para siempre. Los temas que ya jugaste siguen gratis.', de: 'Du spielst schon {used} von {limit} Themen. Sieh dir eine Werbung an, um {n} weitere dauerhaft freizuschalten. Bereits gespielte Themen bleiben kostenlos.', pt: 'Você já joga {used} de {limit} temas. Veja um anúncio para desbloquear mais {n}, para sempre. Os temas que você já jogou continuam grátis.', it: 'Giochi già {used} temi su {limit}. Guarda un annuncio per sbloccarne altri {n}, per sempre. I temi già giocati restano gratuiti.', ar: 'أنت تلعب بالفعل {used} من {limit} مواضيع. شاهد إعلانًا لفتح {n} مواضيع إضافية بشكل دائم. تبقى المواضيع التي لعبتها مجانية.', ja: 'すでに{limit}テーマ中{used}テーマをプレイ中です。広告を見るとさらに{n}テーマが永久に解放されます。プレイ済みのテーマは無料のままです。', ko: '이미 {limit}개 중 {used}개 테마를 플레이 중이에요. 광고를 보면 {n}개를 영구적으로 더 열 수 있어요. 이미 플레이한 테마는 계속 무료예요.', zh: '你已在玩{limit}个主题中的{used}个。观看广告可永久解锁另外{n}个主题。已玩过的主题仍然免费。', pl: 'Grasz już w {used} z {limit} tematów. Obejrzyj reklamę, aby odblokować na stałe {n} kolejne. Tematy, w które już grasz, pozostają darmowe.' },
