  'chest.sub': { fr: 'Crédits, XP ou boost ×2 : ouvre-le pour voir.', en: 'Credits, XP or a ×2 boost: open it to find out.', es: 'Créditos, XP o un boost ×2: ábrelo para verlo.', de: 'Guthaben, XP oder ein ×2-Boost: öffne sie und sieh nach.', pt: 'Créditos, XP ou boost ×2: abra para ver.', it: 'Crediti, XP o boost ×2: aprilo per scoprirlo.', ar: 'رصيد أو نقاط خبرة أو تعزيز ×2: افتحه لترى.', ja: 'クレジット、XP、×2ブースト：開けて確かめよう。', ko: '크레딧, XP 또는 ×2 부스트: 열어서 확인하세요.', zh: '点数、经验或×2加成：打开看看。', pl: 'Kredyty, XP lub boost ×2: otwórz i sprawdź.' },
