  'chest.open_ad': { fr: 'Ouvrir un 2e coffre (pub)', en: 'Open a 2nd chest (ad)', es: 'Abrir un 2.º cofre (anuncio)', de: 'Eine 2. Truhe öffnen (Werbung)', pt: 'Abrir um 2º baú (anúncio)', it: 'Apri un 2° forziere (annuncio)', ar: 'افتح صندوقًا ثانيًا (إعلان)', ja: '2つ目の宝箱を開ける（広告）', ko: '두 번째 상자 열기 (광고)', zh: '打开第二个宝箱（广告）', pl: 'Otwórz 2. skrzynię (reklama)' },
  'chest.done': { fr: 'Reviens demain pour un nouveau coffre.', en: 'Come back tomorrow for a new chest.', es: 'Vuelve mañana para un nuevo cofre.', de: 'Komm morgen für eine neue Truhe wieder.', pt: 'Volte amanhã para um novo baú.', it: 'Torna domani per un nuovo forziere.', ar: 'عد غدًا للحصول على صندوق جديد.', ja: '明日また新しい宝箱が届きます。', ko: '내일 새 상자를 받으러 오세요.', zh: '明天再来领取新宝箱。', pl: 'Wróć jutro po nową skrzynię.' },
  'tuto.tip_speed': { fr: "Plus tu réponds vite, plus tu marques : jusqu’à 20 points par bonne réponse.", en: "The faster you answer, the more you score: up to 20 points per right answer.", es: "Cuanto más rápido respondas, más puntos: hasta 20 por respuesta correcta.", de: "Je schneller du antwortest, desto mehr Punkte: bis zu 20 pro richtiger Antwort.", pt: "Quanto mais rápido responder, mais pontos: até 20 por resposta certa.", it: "Più rispondi in fretta, più punti fai: fino a 20 per risposta giusta.", ar: "كلما أجبت أسرع، ربحت نقاطًا أكثر: حتى 20 نقطة لكل إجابة صحيحة.", ja: "早く答えるほど高得点：正解1問で最大20ポイント。", ko: "빨리 답할수록 점수가 올라가요: 정답당 최대 20점.", zh: "答得越快得分越高：每题答对最多20分。", pl: "Im szybciej odpowiesz, tym więcej punktów: do 20 za dobrą odpowiedź." },
  'tuto.tip_opponent': { fr: "Une coche près de son nom : ton adversaire a répondu. Sa photo s’affichera sur sa réponse.", en: "A tick by their name: your opponent has answered. Their picture will appear on their answer.", es: "Un check junto a su nombre: tu rival ha respondido. Su foto aparecerá en su respuesta.", de: "Ein Haken neben dem Namen: Dein Gegner hat geantwortet. Sein Bild erscheint auf seiner Antwort.", pt: "Um visto ao lado do nome: o adversário respondeu. A foto dele aparecerá na resposta.", it: "Una spunta accanto al nome: l’avversario ha risposto. La sua foto apparirà sulla sua risposta.", ar: "علامة بجانب اسمه: خصمك أجاب. ستظهر صورته على إجابته.", ja: "名前の横にチェック：相手が回答済み。相手のアイコンが選んだ答えに表示されます。", ko: "이름 옆 체크 표시: 상대가 답했어요. 상대 사진이 고른 답에 표시돼요.", zh: "名字旁出现勾号：对手已作答。他的头像会显示在他选的答案上。", pl: "Znaczek przy nazwie: przeciwnik odpowiedział. Jego zdjęcie pojawi się na jego odpowiedzi." },
  'tuto.tip_last': { fr: "Garde des forces : la dernière question rapporte 1,5 fois plus de points.", en: "Save some energy: the last question is worth 1.5× the points.", es: "Guarda fuerzas: la última pregunta vale 1,5 veces más puntos.", de: "Spar dir Kraft auf: Die letzte Frage bringt 1,5-mal so viele Punkte.", pt: "Guarde energia: a última pergunta vale 1,5 vez mais pontos.", it: "Tieni duro: l’ultima domanda vale 1,5 volte i punti.", ar: "احتفظ بتركيزك: السؤال الأخير يمنح 1.5 ضعف النقاط.", ja: "最後まで油断しないで：ラスト問題はポイント1.5倍！", ko: "끝까지 집중하세요: 마지막 문제는 점수가 1.5배예요.", zh: "坚持到底：最后一题得分×1.5。", pl: "Oszczędzaj siły: ostatnie pytanie jest warte 1,5 raza więcej punktów." },
