/** Nom affiché d'un univers (id serveur « ARENA », « arena »…) dans la langue du joueur.
 *  Univers inconnu : `fallback` (libellé serveur) sinon l'id tel quel. */
export function universeName(id: string | null | undefined, fallback?: string): string {
  const key = `universe.${String(id || '').toUpperCase()}`;
  return translations[key] ? t(key) : (fallback || String(id || ''));
}

let currentLanguage: Language = 'fr';

export function setLanguage(lang: Language) {
  currentLanguage = lang;
  AsyncStorage.setItem(LANG_KEY, lang);
}

export async function loadLanguage(): Promise<Language> {
  const saved = await AsyncStorage.getItem(LANG_KEY);
  if (saved && saved in LANGUAGE_NAMES) {
    currentLanguage = saved as Language;
  }
  return currentLanguage;
}

export function getLanguage(): Language {
  return currentLanguage;
}

const LOCALE_MAP: Record<Language, string> = {
  fr: 'fr-FR', en: 'en-US', es: 'es-ES', de: 'de-DE', pt: 'pt-BR',
  it: 'it-IT', pl: 'pl-PL', ar: 'ar-SA', ja: 'ja-JP', ko: 'ko-KR', zh: 'zh-CN',
};

export function getLocale(): string {
  return LOCALE_MAP[currentLanguage] || 'fr-FR';
}

/** Choisit `${base}_one` ou `${base}_many` selon les règles de la langue (fr : 0 et 1 au singulier). */
export function pluralKey(base: string, n: number): string {
  if (isPluralOne(n)) return `${base}_one`;
  // Polonais : 2-4, 22-24… (sauf 12-14) ont leur propre forme (« 2 pojedynki » / « 5 pojedynków »).
  if (currentLanguage === 'pl' && isPolishFew(n) && PL_FEW[`${base}_few`]) return `${base}_few`;
  return `${base}_many`;
}

function isPolishFew(n: number): boolean {
  const i = Math.floor(Math.abs(n));
  return i % 10 >= 2 && i % 10 <= 4 && !(i % 100 >= 12 && i % 100 <= 14);
}

// Formes « few » du polonais, hors de la table principale (aucune autre langue n'en a besoin).
const PL_FEW: Record<string, string> = {
  'pilot.home.streak_few': '{n} dni serii',
  'pilot.mission.play_few': 'Rozegraj {n} pojedynki',
  'pilot.mission.win_few': 'Wygraj {n} pojedynki',
  'pilot.mission.category_few': '{n} pojedynki w kategorii {cat}',
  'pilot.home.duels_few': '{n} pojedynki',
  'pilot.social.games_few': '{n} pojedynki',
  'pilot.results.review_few': '{n} pytania do przejrzenia',
  'pilot.leaderboard.players_few': '{n} gracze',
  'pilot.leaderboard.city_too_small_few': 'Tylko {count} gracze w mieście {city}',
};

// Règles CLDR de la catégorie « one » pour nos 10 langues. Écrites ici car Hermes (moteur JS de
// l'app sur téléphone) n'a pas Intl.PluralRules : l'appeler fait planter l'écran.
function isPluralOne(n: number): boolean {
  const i = Math.floor(Math.abs(n));
  switch (currentLanguage) {
    case 'fr':
    case 'pt': return i === 0 || i === 1;            // 0 et 1 au singulier
    case 'ja':
    case 'ko':
    case 'zh': return false;                         // pas de pluriel grammatical
    default:   return n === 1;                       // en, es, de, it, pl, ar
  }
}

export function t(key: string, params?: Record<string, string>): string {
  const entry = translations[key];
  const few = PL_FEW[key];
  if (!entry && !few) return key;
  let str = few || entry[currentLanguage] || entry['fr'] || key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
    }
  }
  return str;
}
